const root = document.body;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function ensurePanel() {
  if (document.querySelector('#meta-lab')) return document.querySelector('#meta-lab');
  const button = document.createElement('button'); button.id='meta-open'; button.className='meta-open'; button.type='button'; button.innerHTML='<span class="meta-orb">✦</span><span>Meta Copilot</span>'; button.setAttribute('aria-label','Open Tuka Meta Copilot'); document.querySelector('.headtools')?.prepend(button);
  const dialog = document.createElement('dialog'); dialog.id='meta-lab'; dialog.className='meta-dialog';
  dialog.innerHTML='<form method="dialog" class="meta-head"><div><span class="meta-kicker">META HACKATHON BUILD</span><h2>Tuka Copilot</h2><p>Ask about verified network profiles and how Tuka handles your journey.</p></div><button class="meta-close" aria-label="Close">×</button></form><section class="meta-city-section"><div class="meta-section-heading"><div><span class="meta-kicker">CITY-AWARE TRANSIT</span><h3>Choose a network profile</h3></div><span id="meta-city-status" class="meta-status">Loading…</span></div><div id="meta-cities" class="meta-cities"></div></section><section class="meta-chat"><div class="meta-section-heading"><div><span class="meta-kicker">GROUNDED ANSWERS</span><h3>Ask Tuka Copilot</h3></div><span class="meta-lock">Token stays server-side</span></div><div id="meta-chat-log" class="meta-chat-log" aria-live="polite"><p class="meta-message meta-message-ai">I can explain verified city profiles and data freshness. I will never invent a departure.</p></div><form id="meta-ask" class="meta-ask"><input id="meta-question" maxlength="1200" autocomplete="off" placeholder="e.g. What is live in Skopje?" aria-label="Ask Tuka Copilot"><button class="primary">Ask</button></form></section><p class="meta-footnote">Meta Model API answers are informational. Confirm live departures in the Tuka planner before leaving.</p>';
  root.append(dialog); return dialog;
}
function cityCard(city, selected) { const live=city.capabilities.includes('realtime'); return `<button type="button" class="meta-city ${selected?'selected':''}" data-city-id="${esc(city.id)}" aria-pressed="${selected}"><span class="meta-city-top"><strong>${esc(city.name)}</strong><span class="meta-city-pill ${live?'live':''}">${live?'Live':'GTFS'}</span></span><small>${esc(city.provider)} · ${esc(city.timezone)}</small><span>${esc(city.description)}</span></button>`; }
async function loadCities(dialog) { const holder=dialog.querySelector('#meta-cities'); try { const response=await fetch('./api/cities',{headers:{Accept:'application/json'},credentials:'same-origin'}); if(!response.ok)throw Error(); const data=await response.json(); const saved=localStorage.getItem('tuka-meta-city')||'skopje'; holder.innerHTML=(data.cities||[]).map(city=>cityCard(city,city.id===saved)).join(''); dialog.querySelector('#meta-city-status').textContent=`${data.cities?.length||0} profiles`; holder.querySelectorAll('[data-city-id]').forEach(button=>button.addEventListener('click',()=>{localStorage.setItem('tuka-meta-city',button.dataset.cityId); holder.querySelectorAll('[data-city-id]').forEach(next=>{const active=next===button;next.classList.toggle('selected',active);next.setAttribute('aria-pressed',String(active));});dialog.querySelector('#meta-city-status').textContent=`${button.querySelector('strong').textContent} selected`;})); } catch { dialog.querySelector('#meta-city-status').textContent='Profiles unavailable'; holder.innerHTML='<p class="meta-empty">The protected profile service is unavailable. Skopje remains the live default.</p>'; } }
function addMessage(log,text,kind){const item=document.createElement('p');item.className=`meta-message meta-message-${kind}`;item.textContent=text;log.append(item);log.scrollTop=log.scrollHeight;}
function init(){const dialog=ensurePanel();document.querySelector('#meta-open').addEventListener('click',()=>{dialog.showModal();loadCities(dialog);});const form=dialog.querySelector('#meta-ask'),input=dialog.querySelector('#meta-question'),log=dialog.querySelector('#meta-chat-log');form.addEventListener('submit',async event=>{event.preventDefault();const message=input.value.trim();if(!message)return;input.value='';addMessage(log,message,'user');const submit=form.querySelector('button');submit.disabled=true;submit.textContent='Thinking…';try{const response=await fetch('./api/meta/ask',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},credentials:'same-origin',body:JSON.stringify({message})});const data=await response.json().catch(()=>({}));addMessage(log,response.ok?data.answer:(data.error||'Meta Copilot is unavailable.'),response.ok?'ai':'error');}catch{addMessage(log,'Meta Copilot is unavailable. Use the planner for verified journey details.','error');}finally{submit.disabled=false;submit.textContent='Ask';}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
